/**
 * @module navigation-jav8
 * @file Frameset navigation for javadoc generated by a Java 8 JDK.
 * @description Opens a deep link in the class frame of the frameset index page, and
 * switches a class page's member table between the categories its tabs name.
 *
 * The Java 8 doclet does both jobs itself: an inline script in index.html works
 * out which page to open, and script.js redraws the member table. The
 * javadoc-java8 build target replaces both with this one file - it copies it to
 * dist/javadoc/navigation.js, points every page's script.js reference at it,
 * rewrites each tab's javascript:show(N) link as a data-method-filter attribute,
 * and strips the inline target-page script. One file covers both halves because
 * that strip and inject leaves exactly one script slot per page. "Java 8" names
 * the JDK that generates the pages, not a browser this has to run in.
 *
 * Loaded as a classic script, not a module: the frameset's onLoad attribute calls
 * top.loadFrames(), and each generated page hands show() and updateTabs() the
 * methods, tabs and colour names as globals. A module would keep those names to
 * itself.
 * @author dr|z3d
 * @license AGPL3 or later
 */
"use strict";

/** Suffix of every generated page, the only kind of target a deep link may name. */
const HTML_SUFFIX = ".html";

/** The four characters that would break the tab markup, as their entities. */
const ENTITIES = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
};

/**
 * A character that may begin a package or class name: a letter, "$", "_" or any
 * non-ASCII character.
 */
const NAME_START = /[A-Za-z_$\u0080-\uffff]/;

/**
 * A character that may follow a name's first character but not begin one: a digit
 * or a hyphen.
 */
const NAME_REST = /[0-9-]/;

/**
 * Works the page to open out of the frameset's query string.
 *
 * The JDK's index pages carry the target as the whole query string, so its
 * leading "?" is dropped. A value naming another host - anything holding a ":" -
 * is refused rather than loaded, so a deep link cannot leave the documentation.
 * @returns {string} the page to open, or "" when there is no query string or the
 *   value is not one of our pages.
 */
const readTargetPage = () => {
  const page = window.location.search.slice(1);
  if (page === "" || page.includes(":") || !validURL(page)) {
    return "";
  }
  return page;
};

/**
 * The page the frameset opens in its class frame, or "" when the link carries
 * nothing we will load.
 *
 * A top-level binding is lexical rather than a window property, so this is not
 * readable as top.targetPage the way the JDK's own inline script kept its value.
 * That costs nothing here: loadFrames() below is ours and reads the bare
 * identifier. And javadoc-postprocess.sh strips that inline script and links this
 * file in its place, both from the same spot in index.html, so if the strip ever
 * stopped matching, this file would not be linked at all and the JDK's script
 * would still be doing the job.
 */
const targetPage = readTargetPage();

/**
 * Whether a deep-link value names one of our own generated pages.
 *
 * The value has to be a path of name segments ending in ".html", so only the
 * documentation can be reached: an absolute URL, a query string, a fragment and a
 * path that walks up with ".." are all refused. A segment begins with a letter,
 * "$", "_" or a non-ASCII character, which is what a translated package name
 * looks like, and may then carry digits and hyphens. A "/" is never allowed after
 * a ".", which is what stops a class name from being read as a directory.
 * @param {string} page the value from the query string, still percent-encoded.
 * @returns {boolean} true when page is a generated page we are willing to load.
 */
function validURL(page) {
  try {
    page = decodeURIComponent(page);
  } catch {
    return false;
  }
  const dotHtml = page.indexOf(HTML_SUFFIX);
  // The first ".html" has to be the end of the value: a name carrying one in the
  // middle is not a page we generate.
  if (dotHtml === -1 || dotHtml !== page.length - HTML_SUFFIX.length) {
    return false;
  }
  let inName = false;
  let dotted = false;
  for (const ch of page.slice(0, dotHtml)) {
    if (NAME_START.test(ch)) {
      inName = true;
    } else if (NAME_REST.test(ch)) {
      if (!inName) {
        return false;
      }
    } else if (ch === "/" || ch === ".") {
      if (!inName) {
        return false;
      }
      inName = false;
      if (ch === ".") {
        dotted = true;
      } else if (dotted) {
        return false;
      }
    } else {
      return false;
    }
  }
  return true;
}

/**
 * Points the class frame at the page the query string asked for.
 *
 * The frameset's onLoad attribute calls this as top.loadFrames(), which is why it
 * stays a top-level function declaration in a classic script.
 * @returns {void}
 */
function loadFrames() {
  if (targetPage !== "") {
    top.classFrame.location = targetPage;
  }
}

/**
 * Routes clicks on the tab strip to show().
 *
 * Tabs arrive as data-method-filter attributes: javadoc-postprocess.sh rewrites
 * the JDK's javascript:show(N) links to them, and updateTabs() writes the same
 * markup when it redraws the strip. One delegated listener covers every tab on
 * the page, and closest() picks the tab up when the click lands on its text
 * rather than on its anchor.
 * @returns {void}
 */
const initTabs = () => {
  document.body.addEventListener("click", (event) => {
    const tab = event.target.closest("[data-method-filter]");
    if (tab) {
      event.preventDefault();
      show(parseInt(tab.getAttribute("data-method-filter"), 10));
    }
  });
};

document.addEventListener("DOMContentLoaded", initTabs);

/**
 * Shows the member rows of one category and redraws the tab strip.
 *
 * The page's inline script defines methods as a map of row id to the bit mask of
 * the categories that row belongs to, so type is one of those bits: 1 for all
 * methods, 2 for instance, 4 for static, and so on. Shown rows are re-striped as
 * they are revealed so the banding stays continuous across the hidden ones.
 * @param {number} type the category mask to show.
 * @returns {void}
 */
function show(type) {
  let count = 0;
  for (const key in methods) {
    if (!Object.hasOwn(methods, key)) {
      continue;
    }
    const row = document.getElementById(key);
    if (!row) {
      continue;
    }
    if ((methods[key] & type) !== 0) {
      row.style.display = "";
      row.className = count++ % 2 === 0 ? altColor : rowColor;
    } else {
      row.style.display = "none";
    }
  }
  updateTabs(type);
}

/**
 * Escapes text for the tab markup updateTabs() writes, so a label or a category
 * mask can never close the anchor or its attribute.
 * @param {string} value the text to show.
 * @returns {string} the same text with the four markup characters replaced.
 */
function esc(value) {
  return String(value).replace(/[&<>"]/g, (ch) => ENTITIES[ch]);
}

/**
 * Marks one tab of the strip as selected and turns the rest into links to their
 * own category.
 *
 * The page's inline script defines tabs as a map of category mask to an
 * [element id, label] pair. Only the label's contents are rewritten, so the strip
 * keeps its shape and a tab does not move when it becomes the selected one.
 * @param {number} type the category now shown, matched against each tab's mask.
 * @returns {void}
 */
function updateTabs(type) {
  for (const value in tabs) {
    if (!Object.hasOwn(tabs, value)) {
      continue;
    }
    const tab = tabs[value];
    if (!tab) {
      continue;
    }
    const tabNode = document.getElementById(tab[0]);
    if (!tabNode) {
      continue;
    }
    const label = tabNode.firstChild;
    if (!label) {
      continue;
    }
    if (Number(value) === type) {
      tabNode.className = activeTableTab;
      label.innerHTML = esc(tab[1]);
    } else {
      tabNode.className = tableTab;
      label.innerHTML = '<a href="#" data-method-filter="' + esc(value) + '">' +
          esc(tab[1]) + "</a>";
    }
  }
}
